mapper.update:
update reports
set reason_code = #{reasonCode}, reason_detail = #{reasonDetail}
where report_id = #{reportId} and member_id = #{memberId} and delete_yn = 'N' and status = 'PENDING'

update reports
set status = #{status}
where report_id = #{reportId} and status = 'PENDING'

mapper.select:
select *
from reports
where target_type = #{targetType}
order by report_id desc
limit #{start}, #{end}
